const linkBps = 1e9 / 8;            // 1 Gbps in bytes/s
const pkt = 1500;                  // bytes per UDP datagram
const noGso = linkBps / pkt;       // sendmsg() calls/sec, one per packet
const gsoBatch = 64 * 1024;        // 64 KB batched per sendmsg()
const pktsPerBatch = Math.floor(gsoBatch / pkt);
const withGso = noGso / pktsPerBatch;
console.log('syscalls/s no GSO:', Math.round(noGso));
console.log('packets per 64KB batch:', pktsPerBatch);
console.log('syscalls/s with GSO:', Math.round(withGso));
console.log('reduction factor:', Math.round(noGso / withGso) + 'x');
